window.MGProseData("2a132b29022e151f3952462f052db407d182c6bc8db8fd6bb0dd0b87d87d394f",{"html":"\u003cp>\u003cstrong>S1.\u003c/strong> 取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo>∈\u003c/mo>\u003cmi>E\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x_0\\in E\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 使 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f(x_0)\u0026lt;\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。由定义，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>≥\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\ng_F\\ge0,\\qquad g_F(q_Fx_0)\\le f(x_0)\u0026lt;\\infty.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>y\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>y\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">g_F(y_1),g_F(y_2)\u0026lt;\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则对任意 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>ε\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\varepsilon\u0026gt;0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，可选取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x_i\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 满足\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>y\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>y\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmi>ε\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nq_Fx_i=y_i,\\qquad f(x_i)\\le g_F(y_i)+\\varepsilon.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>λ\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">0\u0026lt;\\lambda\u0026lt;1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，由 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的凸性，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable rowspacing=\"0.25em\" columnalign=\"right left\" columnspacing=\"0em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>λ\u003c/mi>\u003cmsub>\u003cmi>y\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmi>λ\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>y\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo>≤\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>λ\u003c/mi>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmi>λ\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmrow>\u003c/mrow>\u003cmo>≤\u003c/mo>\u003cmi>λ\u003c/mi>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>y\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo>−\u003c/mo>\u003cmi>λ\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>y\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmi>ε\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\begin{aligned}\ng_F(\\lambda y_1+(1-\\lambda)y_2)\n\u0026amp;\\le f(\\lambda x_1+(1-\\lambda)x_2)\\\\\n\u0026amp;\\le\\lambda g_F(y_1)+(1-\\lambda)g_F(y_2)+\\varepsilon.\n\\end{aligned}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>ε\u003c/mi>\u003cmo>↓\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\varepsilon\\downarrow0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。若右侧有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo>+\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">+\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，凸性不等式自动成立；端点情形也成立。因此 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">g_F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 凸。\u003c/p>\n\u003cp>因为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>r\u003c/mi>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmi>F\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>K\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_F=r_{KF}q_K\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，对应纤维满足\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo>:\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmi>x\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmo>⋃\u003c/mo>\u003cmrow>\u003cmsub>\u003cmi>r\u003c/mi>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmi>F\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmi>z\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>y\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo>:\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmi>x\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\{x:q_Fx=y\\}\n=\\bigcup_{r_{KF}z=y}\\{x:q_Kx=z\\}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n于是，包括空集情形，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmrow>\u003cmi>inf\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmsub>\u003cmi>r\u003c/mi>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmi>F\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmi>z\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>y\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003cmspace width=\"1em\"/>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\quad g_F(y)=\\inf_{r_{KF}z=y}g_K(z).\\quad}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n上述证明均不需要纤维下确界取到。\u003c/p>\n\u003cp>\u003cstrong>S2.\u003c/strong> 记 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>c\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmi>c\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C_c=\\{x:f(x)\\le c\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的一组基后，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的坐标就是有限个连续线性泛函，因此 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 连续。\u003c/p>\n\u003cp>设 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a=g_F(y)\u0026lt;\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。对每个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">n\\ge1\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，集合\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>n\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmo>∩\u003c/mo>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msubsup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nA_n=C_{a+1/n}\\cap q_F^{-1}(\\{y\\})\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由下确界定义非空，并且是一列递减闭集，均包含在紧集 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmo>+\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C_{a+1}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中。这里闭性来自 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 下半连续和 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 连续。由紧空间中闭集的有限交性质，存在\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>x\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmunder>\u003cmo>⋂\u003c/mo>\u003cmrow>\u003cmi>n\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/munder>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>n\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nx\\in\\bigcap_{n\\ge1}A_n.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n于是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmi>x\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>y\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_Fx=y\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>、\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmi>a\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f(x)\\le a\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，而下确界定义又给出 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≥\u003c/mo>\u003cmi>a\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f(x)\\ge a\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。故\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nf(x)=g_F(y),\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n即有限的纤维下确界取到。\u003c/p>\n\u003cp>因此，对每个有限实数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>c\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">c\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo>:\u003c/mo>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmi>c\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>c\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\{y:g_F(y)\\le c\\}=q_F(C_c).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n右侧是紧集，因 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>F\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F^*\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为 Hausdorff 空间而闭。因此 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">g_F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 下半连续。具体地，若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>t\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">t\u0026lt;g_F(y)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，选取实数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>a\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 满足 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>t\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">t\u0026lt;a\u0026lt;g_F(y)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo>:\u003c/mo>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>\u0026gt;\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo>×\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmo>−\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\{v:g_F(v)\u0026gt;a\\}\\times(-\\infty,a)\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n是包含 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(y,t)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 且与上图不交的开集，故实高度上图闭。\u003c/p>\n\u003cp>\u003cstrong>S3.\u003c/strong> 在紧集 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>c\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C_c\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中定义\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>c\u003c/mi>\u003c/msub>\u003cmo>∩\u003c/mo>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msubsup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmsub>\u003cmi>y\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nA_F=C_c\\cap q_F^{-1}(\\{y_F\\}).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由 S2 的取到性及 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>y\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmi>c\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">g_F(y_F)\\le c\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，每个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">A_F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 都非空且闭；特别地，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>c\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C_c\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 非空。\u003c/p>\n\u003cp>对任意有限多个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>F\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo separator=\"true\">,\u003c/mo>\u003cmo>…\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmsub>\u003cmi>F\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F_1,\\ldots,F_m\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>F\u003c/mi>\u003cmn>1\u003c/mn>\u003c/msub>\u003cmo>+\u003c/mo>\u003cmo>⋯\u003c/mo>\u003cmo>+\u003c/mo>\u003cmsub>\u003cmi>F\u003c/mi>\u003cmi>m\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nK=F_1+\\cdots+F_m.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n兼容性给出\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo>⊆\u003c/mo>\u003cmunderover>\u003cmo>⋂\u003c/mo>\u003cmrow>\u003cmi>i\u003c/mi>\u003cmo>=\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003cmi>m\u003c/mi>\u003c/munderover>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmsub>\u003cmi>F\u003c/mi>\u003cmi>i\u003c/mi>\u003c/msub>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nA_K\\subseteq\\bigcap_{i=1}^m A_{F_i}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n所以这族闭集具有有限交性质。由 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>c\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C_c\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 紧，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmunder>\u003cmo>⋂\u003c/mo>\u003cmi>F\u003c/mi>\u003c/munder>\u003cmsub>\u003cmi>A\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo mathvariant=\"normal\">≠\u003c/mo>\u003cmi mathvariant=\"normal\">∅\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\bigcap_F A_F\\ne\\varnothing.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n取交集中的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>x\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，即有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmi>c\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f(x)\\le c\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmi>x\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>y\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">q_Fx=y_F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 对所有 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 成立。\u003c/p>\n\u003cp>若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>x\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x\u0026#x27;\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 也满足全部观测条件，则取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">span\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>φ\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F=\\operatorname{span}\\{\\varphi\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，可得\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>φ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo>−\u003c/mo>\u003cmsup>\u003cmi>x\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003cmspace width=\"2em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>φ\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi>E\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\varphi(x-x\u0026#x27;)=0\\qquad(\\varphi\\in E\u0026#x27;).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\nHausdorff 局部凸空间的连续对偶由 Hahn–Banach 定理分离点，故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>x\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmi>x\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x=x\u0026#x27;\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。因此构造可写为\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmspace width=\"1em\"/>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmo>⋂\u003c/mo>\u003cmi>F\u003c/mi>\u003c/munder>\u003cmo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">(\u003c/mo>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>c\u003c/mi>\u003c/msub>\u003cmo>∩\u003c/mo>\u003cmsubsup>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msubsup>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmsub>\u003cmi>y\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003cmspace width=\"1em\"/>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\quad \\{x\\}=\\bigcap_F\n\\bigl(C_c\\cap q_F^{-1}(\\{y_F\\})\\bigr).\\quad}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>\u003cstrong>S4.\u003c/strong> 结论成立。先说明闭上图包络的构造。\u003c/p>\n\u003cp>对非负凸函数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>u\u003c/mi>\u003cmo>:\u003c/mo>\u003cmi>V\u003c/mi>\u003cmo>→\u003c/mo>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmo stretchy=\"false\">]\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">u:V\\to[0,\\infty]\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>u\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmover accent=\"true\">\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmo stretchy=\"true\">‾\u003c/mo>\u003c/mover>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nC_u=\\overline{\\operatorname{epi}_{\\mathbb R}(u)}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n（取所在空间 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>V\u003c/mi>\u003cmo>×\u003c/mo>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">V\\times\\mathbb R\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的闭包）。该集合闭、凸、沿高度方向向上封闭，并包含于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>V\u003c/mi>\u003cmo>×\u003c/mo>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">V\\times[0,\\infty)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。故每个竖直截面或者为空，或者为某个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">[a,\\infty)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，其中 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>a\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">a\\ge0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。于是唯一确定函数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\bar u\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，使\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>u\u003c/mi>\u003c/msub>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\operatorname{epi}_{\\mathbb R}(\\bar u)=C_u.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n它非负、下半连续、凸，且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmo>≤\u003c/mo>\u003cmi>u\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\bar u\\le u\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>u\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\\le u\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 且 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的上图闭，则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>u\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>⊆\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmo>⟹\u003c/mo>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmi>C\u003c/mi>\u003cmi>u\u003c/mi>\u003c/msub>\u003cmo>⊆\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>v\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\operatorname{epi}_{\\mathbb R}(u)\n\\subseteq\\operatorname{epi}_{\\mathbb R}(v)\n\\quad\\Longrightarrow\\quad\nC_u\\subseteq\\operatorname{epi}_{\\mathbb R}(v),\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmover accent=\"true\">\u003cmi>u\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\\le\\bar u\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。这个论证允许 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>v\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">v\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 同时取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">-\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 和 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo>+\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">+\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>现在仅用全部记录定义\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmspace width=\"2em\"/>\u003cmi>G\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmrow>\u003cmi>sup\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmi>dim\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmi>F\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003cmspace width=\"2em\"/>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\qquad\nG(x)=\\sup_{\\dim F\u0026lt;\\infty}\\bar g_F(q_Fx).\n\\qquad}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n每一项下半连续、凸且非负，其上确界也有这些性质，并且\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo>≤\u003c/mo>\u003cmi>G\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n0\\le G(x)\\le f(x).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n特别地，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>G\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">G(x_0)\u0026lt;\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。\u003c/p>\n\u003cp>扩大观测空间时，有\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>r\u003c/mi>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmi>F\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>F\u003c/mi>\u003cmo>⊆\u003c/mo>\u003cmi>K\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003cmspace width=\"1em\"/>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\quad\n\\bar g_F(r_{KF}z)\\le\\bar g_K(z),\\qquad F\\subseteq K.\n\\quad}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n事实上，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>r\u003c/mi>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmi>F\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">r_{KF}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 连续线性，故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>∘\u003c/mo>\u003cmsub>\u003cmi>r\u003c/mi>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmi>F\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\bar g_F\\circ r_{KF}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 下半连续且凸；S1 给出\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>r\u003c/mi>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmi>F\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>r\u003c/mi>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmi>F\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\bar g_F(r_{KF}z)\\le g_F(r_{KF}z)\\le g_K(z),\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n再用 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>K\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\bar g_K\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的最大性即可。特别地，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\bar g_F(q_Fx)\\le\\bar g_K(q_Kx),\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n所以恢复公式中的函数随观测空间扩大而单调增加。\u003c/p>\n\u003cp>下面证明最大性，核心是\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>G\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmover accent=\"true\">\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmo stretchy=\"true\">‾\u003c/mo>\u003c/mover>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003cmspace width=\"1em\"/>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(1)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\quad\n\\operatorname{epi}_{\\mathbb R}(G)\n=\\overline{\\operatorname{epi}_{\\mathbb R}(f)}.\n\\quad} \\tag{1}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n令 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>×\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">i\u003c/mi>\u003cmi mathvariant=\"normal\">d\u003c/mi>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_F=q_F\\times\\mathrm{id}_{\\mathbb R}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。首先，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmtable width=\"100%\">\u003cmtr>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmrow>\u003cmover accent=\"true\">\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmo stretchy=\"true\">‾\u003c/mo>\u003c/mover>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mtd>\u003cmtd width=\"50%\">\u003c/mtd>\u003cmtd>\u003cmtext>(2)\u003c/mtext>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003cannotation encoding=\"application/x-tex\">\n\\overline{P_F(\\operatorname{epi}_{\\mathbb R}(f))}\n=\\operatorname{epi}_{\\mathbb R}(\\bar g_F). \\tag{2}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n确实，投影上图包含于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">g_F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的上图；反过来，若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmi>t\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">g_F(y)\\le t\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则对每个 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>ε\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\varepsilon\u0026gt;0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 可选 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>x\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 使\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmi>x\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>ε\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nq_Fx=y,\\qquad f(x)\u0026lt;t+\\varepsilon.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因此 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo>+\u003c/mo>\u003cmi>ε\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(y,t+\\varepsilon)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 属于投影上图，得到其闭包包含 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">g_F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的上图，从而证明 (2)。\u003c/p>\n\u003cp>记 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>C\u003c/mi>\u003cmo>=\u003c/mo>\u003cmover accent=\"true\">\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmo stretchy=\"true\">‾\u003c/mo>\u003c/mover>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C=\\overline{\\operatorname{epi}_{\\mathbb R}(f)}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。由 (2) 和 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>P\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">P_F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 连续，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>C\u003c/mi>\u003cmo>⊆\u003c/mo>\u003cmunder>\u003cmo>⋂\u003c/mo>\u003cmi>F\u003c/mi>\u003c/munder>\u003cmsubsup>\u003cmi>P\u003c/mi>\u003cmi>F\u003c/mi>\u003cmrow>\u003cmo>−\u003c/mo>\u003cmn>1\u003c/mn>\u003c/mrow>\u003c/msubsup>\u003cmo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">(\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo fence=\"true\" stretchy=\"true\" minsize=\"1.2em\" maxsize=\"1.2em\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>G\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nC\\subseteq\\bigcap_F P_F^{-1}\n\\bigl(\\operatorname{epi}_{\\mathbb R}(\\bar g_F)\\bigr)\n=\\operatorname{epi}_{\\mathbb R}(G).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n反之，若 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo mathvariant=\"normal\">∉\u003c/mo>\u003cmi>C\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(x,t)\\notin C\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，由于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>C\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是 Hausdorff 局部凸空间 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>E\u003c/mi>\u003cmo>×\u003c/mo>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">E\\times\\mathbb R\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 中的非空闭凸集，几何 Hahn–Banach 分离定理给出\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>φ\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi>E\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\varphi\\in E\u0026#x27;\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>、\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>b\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo>∈\u003c/mo>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">b,a\\in\\mathbb R\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，使\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>φ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmi>b\u003c/mi>\u003cmi>t\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>φ\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmi>b\u003c/mi>\u003cmi>s\u003c/mi>\u003cmspace width=\"2em\"/>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>∈\u003c/mo>\u003cmi>C\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\varphi(x)+bt\u0026lt;a\\le\\varphi(z)+bs\n\\qquad((z,s)\\in C).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi mathvariant=\"normal\">span\u003c/mi>\u003cmo>⁡\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmi>φ\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F=\\operatorname{span}\\{\\varphi\\}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。投影上图及其闭包均包含于闭半空间\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>:\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>φ\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>+\u003c/mo>\u003cmi>b\u003c/mi>\u003cmi>s\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmi>a\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\{(y,s):y(\\varphi)+bs\\ge a\\},\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n而 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmi>x\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(q_Fx,t)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 不在其中。由 (2)，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmi>x\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo mathvariant=\"normal\">∉\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n(q_Fx,t)\\notin\\operatorname{epi}_{\\mathbb R}(\\bar g_F),\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>x\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo mathvariant=\"normal\">∉\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>G\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(x,t)\\notin\\operatorname{epi}_{\\mathbb R}(G)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。这证明 (1)。\u003c/p>\n\u003cp>于是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>G\u003c/mi>\u003cmo>=\u003c/mo>\u003cmover accent=\"true\">\u003cmi>f\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">G=\\bar f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。对题设任何竞争函数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>h\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">h\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，由 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>h\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>f\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">h\\le f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 及其上图闭，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>G\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmover accent=\"true\">\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmo stretchy=\"true\">‾\u003c/mo>\u003c/mover>\u003cmo>⊆\u003c/mo>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>h\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\operatorname{epi}_{\\mathbb R}(G)\n=\\overline{\\operatorname{epi}_{\\mathbb R}(f)}\n\\subseteq\\operatorname{epi}_{\\mathbb R}(h),\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n即 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>h\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmi>G\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">h\\le G\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，包括允许同时取两种无穷值的情形。\u003c/p>\n\u003cp>\u003cstrong>S5.\u003c/strong> 不一定。令\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>C\u003c/mi>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>∈\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003cmo>:\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmi>t\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmi>s\u003c/mi>\u003cmi>t\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo stretchy=\"false\">{\u003c/mo>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>:\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmtext> \u003c/mtext>\u003cmi>t\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>s\u003c/mi>\u003cmo stretchy=\"false\">}\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nC=\\{(s,t)\\in\\mathbb R^2:s\\ge0,\\ t\\ge0,\\ st\\ge1\\}\n=\\{(s,t):s\u0026gt;0,\\ t\\ge1/s\\},\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n并定义\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>∈\u003c/mo>\u003cmi>C\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo>+\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi>t\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo mathvariant=\"normal\">∉\u003c/mo>\u003cmi>C\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mrow>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nf(s,t)=\n\\begin{cases}\n0,\u0026amp;(s,t)\\in C,\\\\\n+\\infty,\u0026amp;(s,t)\\notin C.\n\\end{cases}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n集合 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>C\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 由连续不等式定义，因而闭；由于 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>↦\u003c/mo>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>s\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">s\\mapsto1/s\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 在 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(0,\\infty)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 上凸，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>C\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">C\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 也凸。又 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>1\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>∈\u003c/mo>\u003cmi>C\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(1,1)\\in C\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，而\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmi>C\u003c/mi>\u003cmo>×\u003c/mo>\u003cmo stretchy=\"false\">[\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\operatorname{epi}_{\\mathbb R}(f)=C\\times[0,\\infty),\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n所以 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>f\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">f\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 满足本阶段全部条件。\u003c/p>\n\u003cp>取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 为第一坐标泛函张成的空间，将 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>F\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F^*\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 识别为 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\mathbb R\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo>+\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mrow>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\ng_F(s)=\n\\begin{cases}\n0,\u0026amp;s\u0026gt;0,\\\\\n+\\infty,\u0026amp;s\\le0.\n\\end{cases}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n其上图包含 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>1\u003c/mn>\u003cmi mathvariant=\"normal\">/\u003c/mi>\u003cmi>n\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(1/n,0)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，却不包含极限点 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">(0,0)\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">g_F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 不下半连续。\u003c/p>\n\u003cp>\u003cstrong>S6.\u003c/strong> 由 S4 的公式 (1)，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>G\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>f\u003c/mi>\u003cmtext>  \u003c/mtext>\u003cmo>⟺\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmover accent=\"true\">\u003cmrow>\u003cmsub>\u003cmrow>\u003cmi mathvariant=\"normal\">epi\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003c/mrow>\u003cmo stretchy=\"true\">‾\u003c/mo>\u003c/mover>\u003cmtext>  \u003c/mtext>\u003cmo>⟺\u003c/mo>\u003cmtext>  \u003c/mtext>\u003cmi>f\u003c/mi>\u003cmtext> 下半连续\u003c/mtext>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\nG=f\n\\iff \\operatorname{epi}_{\\mathbb R}(f)\n=\\overline{\\operatorname{epi}_{\\mathbb R}(f)}\n\\iff f\\text{ 下半连续}.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>对 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>F\u003c/mi>\u003cmo>⊆\u003c/mo>\u003cmi>K\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">F\\subseteq K\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，记\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>p\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmunder>\u003cmrow>\u003cmi>inf\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmsub>\u003cmi>r\u003c/mi>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmi>F\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmi>z\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>y\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\np(y)=\\inf_{r_{KF}z=y}\\bar g_K(z).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\nS1 的同一近似取值论证适用于凸函数 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>K\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\bar g_K\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 和线性映射 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>r\u003c/mi>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmi>F\u003c/mi>\u003c/mrow>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">r_{KF}\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，故 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>p\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">p\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 非负且凸。它也至少一点有限：取此前的 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">x_0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，则\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>p\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>q\u003c/mi>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmsub>\u003cmi>x\u003c/mi>\u003cmn>0\u003c/mn>\u003c/msub>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>\u0026lt;\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\np(q_Fx_0)\\le\\bar g_K(q_Kx_0)\\le f(x_0)\u0026lt;\\infty.\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n由 S4 的扩大观测关系、\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>K\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\bar g_K\\le g_K\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 及 S1，\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmi>p\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\bar g_F(y)\\le p(y)\\le g_F(y).\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n因此，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>F\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\bar g_F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 是 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>p\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">p\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span> 的下半连续凸下界，给出\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>≤\u003c/mo>\u003cmover accent=\"true\">\u003cmi>p\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\bar g_F\\le\\bar p\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>；而 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>p\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmo>≤\u003c/mo>\u003cmi>p\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\bar p\\le p\\le g_F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，又给出\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmover accent=\"true\">\u003cmi>p\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmo>≤\u003c/mo>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>F\u003c/mi>\u003c/msub>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\bar p\\le\\bar g_F\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。所以\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmenclose notation=\"box\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmstyle scriptlevel=\"0\" displaystyle=\"true\">\u003cmrow>\u003cmspace width=\"1em\"/>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmover accent=\"true\">\u003cmrow>\u003cmo fence=\"true\">(\u003c/mo>\u003cmi>y\u003c/mi>\u003cmo>⟼\u003c/mo>\u003cmunder>\u003cmrow>\u003cmi>inf\u003c/mi>\u003cmo>⁡\u003c/mo>\u003c/mrow>\u003cmrow>\u003cmsub>\u003cmi>r\u003c/mi>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmi>F\u003c/mi>\u003c/mrow>\u003c/msub>\u003cmi>z\u003c/mi>\u003cmo>=\u003c/mo>\u003cmi>y\u003c/mi>\u003c/mrow>\u003c/munder>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>z\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo fence=\"true\">)\u003c/mo>\u003c/mrow>\u003cmo stretchy=\"true\">‾\u003c/mo>\u003c/mover>\u003cmi mathvariant=\"normal\">.\u003c/mi>\u003cmspace width=\"1em\"/>\u003c/mrow>\u003c/mstyle>\u003c/mstyle>\u003c/mstyle>\u003c/menclose>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\n\\boxed{\\quad\n\\bar g_F\n=\\overline{\\left(y\\longmapsto\n\\inf_{r_{KF}z=y}\\bar g_K(z)\\right)}.\n\\quad}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\u003c/p>\n\u003cp>最外层包络不能总省去。沿用 S5 的例子，取 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>K\u003c/mi>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmi>E\u003c/mi>\u003cmo mathvariant=\"normal\" lspace=\"0em\" rspace=\"0em\">′\u003c/mo>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">K=E\u0026#x27;\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，通过自然坐标识别 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsup>\u003cmi>K\u003c/mi>\u003cmo>∗\u003c/mo>\u003c/msup>\u003cmo>=\u003c/mo>\u003cmsup>\u003cmi mathvariant=\"double-struck\">R\u003c/mi>\u003cmn>2\u003c/mn>\u003c/msup>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">K^*=\\mathbb R^2\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>。此时\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>K\u003c/mi>\u003c/msub>\u003cmo>=\u003c/mo>\u003cmi>f\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\ng_K=f,\\qquad \\bar g_K=f,\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n所以\n\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\" display=\"block\">\u003csemantics>\u003cmrow>\u003cmi>p\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmsub>\u003cmi>g\u003c/mi>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>\u0026gt;\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo>+\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>≤\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mrow>\u003cmspace width=\"2em\"/>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmi>s\u003c/mi>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmrow>\u003cmo fence=\"true\">{\u003c/mo>\u003cmtable rowspacing=\"0.36em\" columnalign=\"left left\" columnspacing=\"1em\">\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>≥\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003cmtr>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmo>+\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003cmo separator=\"true\">,\u003c/mo>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003cmtd>\u003cmstyle scriptlevel=\"0\" displaystyle=\"false\">\u003cmrow>\u003cmi>s\u003c/mi>\u003cmo>\u0026lt;\u003c/mo>\u003cmn>0.\u003c/mn>\u003c/mrow>\u003c/mstyle>\u003c/mtd>\u003c/mtr>\u003c/mtable>\u003c/mrow>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\np(s)=g_F(s)=\n\\begin{cases}\n0,\u0026amp;s\u0026gt;0,\\\\\n+\\infty,\u0026amp;s\\le0,\n\\end{cases}\n\\qquad\n\\bar g_F(s)=\n\\begin{cases}\n0,\u0026amp;s\\ge0,\\\\\n+\\infty,\u0026amp;s\u0026lt;0.\n\\end{cases}\n\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>\n特别地，\u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmi>p\u003c/mi>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmo>+\u003c/mo>\u003cmi mathvariant=\"normal\">∞\u003c/mi>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">p(0)=+\\infty\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，而 \u003cspan class=\"katex\">\u003cmath xmlns=\"http://www.w3.org/1998/Math/MathML\">\u003csemantics>\u003cmrow>\u003cmsub>\u003cmover accent=\"true\">\u003cmi>g\u003c/mi>\u003cmo>ˉ\u003c/mo>\u003c/mover>\u003cmi>F\u003c/mi>\u003c/msub>\u003cmo stretchy=\"false\">(\u003c/mo>\u003cmn>0\u003c/mn>\u003cmo stretchy=\"false\">)\u003c/mo>\u003cmo>=\u003c/mo>\u003cmn>0\u003c/mn>\u003c/mrow>\u003cannotation encoding=\"application/x-tex\">\\bar g_F(0)=0\u003c/annotation>\u003c/semantics>\u003c/math>\u003c/span>，两者确实不同。\u003c/p>\n","source":"assets/content/2a132b29022e151f3952462f052db407d182c6bc8db8fd6bb0dd0b87d87d394f.html"});
